item.command:
/bin/zsh -lc "for scenario in happy rate-limit transient-503 permanent-429 bad-request; do
  curl -fsS -X POST http://127.0.0.1:62139/control/reset -H 'content-type: application/json' --data \"{\\\"scenario\\\":\\\""'$scenario'"\\\"}\" -o /dev/null
  case \""'$scenario" in
    happy) curl -sS -o /dev/null -w "$scenario first=%{http_code}'"\\n\" http://127.0.0.1:62139/tickets ;;
    rate-limit|transient-503) curl -sS -o /dev/null -w \""'$scenario first=%{http_code}'"\\n\" http://127.0.0.1:62139/tickets; curl -sS -o /dev/null -w \""'$scenario second=%{http_code}'"\\n\" http://127.0.0.1:62139/tickets ;;
    permanent-429) for attempt in 1 2 3; do curl -sS -o /dev/null -w \""'$scenario attempt-$attempt=%{http_code}'"\\n\" http://127.0.0.1:62139/tickets; done ;;
    bad-request) curl -sS -o /dev/null -w \""'$scenario=%{http_code}'"\\n\" 'http://127.0.0.1:62139/tickets?cursor=invalid' ;;
  esac
  curl -fsS http://127.0.0.1:62139/control/stats
 done"

